/**
 * Tests binary find functionality with sample datasets.
 
  * Finds the first occurrence of an element in a sorted range using a binary search algorithm.
 *
 * @param first beginning of the sorted range
 * @param last end of the sorted range
 * @param value element to be searched
 * @return iterator pointing to the first occurrence of the element if found
 
  * Finds the last possible position to insert an element in a sorted range without violating the ordering.
 *
 * @param first beginning of the sorted range
 * @param last end of the sorted range
 * @param value element for which the insertion point is to be determined
 * @return iterator pointing to the insertion point
 
  * Performs a binary search to find an element in a sorted range.
 *
 * @param first beginning of the sorted range
 * @param last end of the sorted range
 * @param value element to be searched
 * @return iterator pointing to the element if found, otherwise end of the range
 */void testBinaryFind() {
  std::vector<int> data = {1, 1, 2, 3, 3, 3, 3, 4, 4, 4, 5, 5, 6};

  auto lower = cuda_std::lower_bound(data.begin(), data.end(), 4);
  auto upper = cuda_std::upper_bound(data.begin(), data.end(), 4);

  std::copy(lower, upper, std::ostream_iterator<int>(std::cout, " "));

  std::cout << '\n';

  // classic binary search, returning a value only if it is present

  data = {1, 2, 4, 6, 9, 10};

  auto test = [&](auto v) {
    auto it = cuda_std::binary_find(data.cbegin(), data.cend(), v);

    if (it != data.cend())
      std::cout << *it << " found at index " << std::distance(data.cbegin(), it) << std::endl;
    else
      std::cout << v << " non found" << std::endl;
  };

  test(4);
  test(5);
}

int main() { testBinaryFind(); }
